function validate([k, n]) {
  if (!Number.isInteger(k) || k < 2 || k > 9) return 'k is a whole number from 2 to 9.';
  if (!Number.isInteger(n) || n < 1 || n > 30) return 'n is a whole number from 1 to 30.';
  return null;
}

