function kMirror(k, n) {
  const reversed = [0];
  let sum = 0;
  let found = 0;
  for (let start = 1; ; start *= 10) {
    for (const odd of [true, false]) {
      for (let half = start; half < start * 10; half++) {
        const last = half % 10;
        const prefix = (half - last) / 10;
        const front = odd ? half : half * 10 + last;
        const candidate = front * start + reversed[prefix];
        const digits = candidate.toString(k);
        let left = 0;
        let right = digits.length - 1;
        while (left < right && digits[left] === digits[right]) {
          left++;
          right--;
        }
        if (left >= right) {
          sum += candidate;
          found++;
          if (found === n) return sum;
        }
      }
    }
    for (let half = start; half < start * 10; half++) {
      const last = half % 10;
      reversed[half] = last * start + reversed[(half - last) / 10];
    }
  }
}

