function kMirror(k, n) {
  // Walk the base-k palindromes in increasing order and keep those that are decimal palindromes too.
  const flip = (text) => text.split('').reverse().join('');
  let sum = 0;
  let count = 0;
  for (let length = 1; count < n; length++) {
    const halfLength = Math.ceil(length / 2);
    for (let half = k ** (halfLength - 1); half < k ** halfLength && count < n; half++) {
      const left = half.toString(k);
      const value = parseInt(left + flip(left).slice(length % 2), k);
      const text = String(value);
      if (text === flip(text)) {
        sum += value;
        count++;
      }
    }
  }
  return sum;
}

