function generate(rand, size) {
  const k = 2 + Math.floor(rand() * 8);
  if (size === 'large') {
    // The 30th 4- and 7-mirror numbers are huge, so those bases stop a little earlier to stay inside the time limit.
    const top = k === 7 ? 25 : k === 4 ? 29 : 30;
    return [k, top - Math.floor(rand() * 4)];
  }
  // Small counts keep every k-mirror number involved below 100,000.
  const cap = [0, 0, 18, 18, 15, 13, 20, 13, 22, 20][k];
  return [k, 1 + Math.floor(rand() * cap)];
}
